INSERT INTO public.reviews (product_id, author, rating, text, verified, created_at) VALUES
((SELECT id FROM public.products WHERE slug = 'rose-berry-essence-oil'), 'Sarah M.', 5, 'The Rose Berry oil is absolutely divine. The scent is soft and nurturing, perfect for my evening meditation. I can feel the rose quartz energy every time I use it.', TRUE, '2026-03-15T00:00:00Z'),
((SELECT id FROM public.products WHERE slug = 'oud-wood-essence-oil'), 'James T.', 5, 'Oud Wood is incredible. The depth and richness of the scent is unlike anything I''ve experienced. It truly transforms my meditation space.', TRUE, '2026-03-10T00:00:00Z'),
((SELECT id FROM public.products WHERE slug = 'citrus-mint-essence-oil'), 'Michelle L.', 4, 'Love the Citrus Mint oil — it''s my go-to morning ritual now. Wakes me up and keeps me focused throughout the day. Great quality.', TRUE, '2026-03-05T00:00:00Z'),
((SELECT id FROM public.products WHERE slug = 'white-musk-essence-oil'), 'Elena G.', 5, 'White Musk is my daily signature. It''s clean, balanced, and somehow makes every space feel more peaceful. Layering it with Rose Berry is magical.', TRUE, '2026-02-20T00:00:00Z'),
((SELECT id FROM public.products WHERE slug = 'ocean-vetiver-essence-oil'), 'David K.', 5, 'Ocean Vetiver brings a sense of deep calm. The aquamarine crystal pairing is perfect — I use it before every important meeting.', TRUE, '2026-02-15T00:00:00Z');

